const p = $json.payload;
const v = p.profile?.creative?.voice || {};
const MAP = {
  'calm|measured': 'voice_calm_neutral',
  'brisk|explanatory': 'voice_clear_explainer',
  'fast|enthusiastic-but-real': 'voice_energetic_ugc',
  'conversational|straight-talking': 'voice_plain_local'
};
const key = `${v.pace || 'medium'}|${v.style || 'conversational'}`;
const voice_id = p.voice_id || MAP[key] || $env.DEFAULT_VOICE_ID;
const lines = (p.beats || []).map(b => b.spoken).filter(Boolean);
return [{ json: { voice_id, text: p.text || lines.join(' '), lines, locale: $('Envelope In').first().json.locale, stability: 0.45, similarity_boost: 0.75 } }];

// Word-level timings are what let captions and beat cuts land on the right frame.
// Without them the renderer guesses, and the guess is visible.
const a = $json.alignment || {};
const chars = a.characters || [];
const starts = a.character_start_times_seconds || [];
const ends = a.character_end_times_seconds || [];
const words = [];
let cur = '', s = null;
for (let i = 0; i < chars.length; i++) {
  const c = chars[i];
  if (s === null) s = starts[i];
  if (/\s/.test(c)) { if (cur) words.push({ word: cur, start_s: s, end_s: ends[i] }); cur = ''; s = null; }
  else cur += c;
}
if (cur) words.push({ word: cur, start_s: s, end_s: ends[ends.length - 1] });
return [{ json: { words, duration_s: ends[ends.length - 1] || null, word_count: words.length } }];
